'use client';

import React, { useEffect, useRef, useState } from 'react';
import { X } from "react-bootstrap-icons";
import { createPortal } from 'react-dom';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: React.ReactNode;
  children: React.ReactNode;
  width?: string;
  headerStyle?: 'default' | 'branding';
  id?: string;
  disableClose?: boolean;
}

export const Modal = ({ isOpen, onClose, title, children, width = 'max-w-3xl', headerStyle = 'default', id, disableClose = false }: ModalProps) => {
  const modalRef = useRef<HTMLDivElement>(null);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    return () => setMounted(false);
  }, []);

  // Focus trapping and restoration
  useEffect(() => {
    if (!isOpen) return;

    const previousFocus = document.activeElement as HTMLElement;

    // Focus the first focusable element inside the modal
    if (modalRef.current) {
      const focusables = modalRef.current.querySelectorAll(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      );
      if (focusables.length > 0) {
        (focusables[0] as HTMLElement).focus();
      }
    }

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Tab') {
        if (!modalRef.current) return;
        const focusables = modalRef.current.querySelectorAll(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        if (focusables.length === 0) return;
        const first = focusables[0] as HTMLElement;
        const last = focusables[focusables.length - 1] as HTMLElement;

        if (e.shiftKey) {
          if (document.activeElement === first) {
            last.focus();
            e.preventDefault();
          }
        } else {
          if (document.activeElement === last) {
            first.focus();
            e.preventDefault();
          }
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      if (previousFocus && typeof previousFocus.focus === 'function') {
        previousFocus.focus();
      }
    };
  }, [isOpen]);

  // Close on Escape key press
  useEffect(() => {
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && !disableClose) onClose();
    };
    if (isOpen) {
      document.addEventListener('keydown', handleEscape);
      document.body.style.overflow = 'hidden';
    }
    return () => {
      document.removeEventListener('keydown', handleEscape);
      document.body.style.overflow = 'unset';
    };
  }, [isOpen, onClose, disableClose]);

  // Close on click outside content area
  const handleBackdropClick = (event: React.MouseEvent) => {
    if (disableClose) return;
    if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
      onClose();
    }
  };

  if (!isOpen || !mounted) return null;

  // Header Styles
  const isBranding = headerStyle === 'branding';
  const headerBg = isBranding ? 'bg-[#4aaada]' : 'bg-white border-b border-gray-200';
  const titleColor = isBranding ? 'text-white' : 'text-gray-900';
  const closeBtnColor = isBranding ? 'text-white/80 hover:text-white hover:bg-white/20' : 'text-gray-400 hover:text-gray-600 hover:bg-gray-100';

  return createPortal(
    <div
      id={id ? `${id}-wrapper` : undefined}
      className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-in fade-in duration-200"
      onClick={handleBackdropClick}
    >
      <div
        ref={modalRef}
        id={id}
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
        className={`bg-white rounded-lg shadow-xl w-full ${width} max-h-[90vh] flex flex-col animate-in zoom-in-95 duration-200`}
      >
        {/* Header */}
        <div className={`flex items-center justify-between px-4 py-3 rounded-t-md shrink-0 ${headerBg}`}>
          <h2 id="modal-title" className={`text-base font-bold ${titleColor}`}>{title}</h2>
          {!disableClose && (
            <button
              onClick={onClose}
              aria-label="Close modal"
              className={`p-1 rounded-full transition-colors ${closeBtnColor}`}
            >
              <X size={24} />
            </button>
          )}
        </div>

        {/* Content - Scrollable */}
        <div className="p-4 overflow-y-auto flex-1">
          {children}
        </div>
      </div>
    </div>,
    document.body
  );
};

